
#' Plot Two-Way Sensitivity Analysis
#'
#' @description
#' Produces heatmaps or contour-enhanced sensitivity surfaces
#' from deterministic two-way sensitivity analysis results
#' generated by compute_twsa().
#'
#' Both graphical representations share the same analytical
#' preparation, economic outcomes, colour scales, grouping
#' logic and panel validation.
#'
#' @param data An object of class "twsa_result".
#' @param type Graphical representation: "heatmap" or "contour".
#' @param metric Economic outcome: "nmb", "icer",
#'   "delta_cost" or "delta_effect".
#' @param lambda Willingness-to-pay threshold for NMB.
#' @param impact_mode Either "absolute" or "relative".
#' @param mode Either "Overall" or "Subgroups".
#' @param facet_by Faceting directive: "none", "dataset",
#'   "comparison", "pair", "subgroup", "subgroup_var"
#'   or "subgroup_level".
#' @param plot_by Independent plot grouping: "none", "dataset",
#'   "comparison", "pair", "subgroup_var" or "subgroup_level".
#' @param filter_expr Optional filtering expression.
#' @param facet_scales Facet scaling behaviour.
#' @param palette Two colours defining the colour scale.
#' @param midpoint Optional midpoint for a diverging scale.
#'   Defaults to zero for NMB and relative impacts.
#' @param midpoint_color Colour at the midpoint.
#' @param show_values Display numerical values inside cells.
#'   NULL enables values automatically for three-level heatmaps.
#' @param digits Number of decimal places for cell labels.
#' @param n_contours Number of contour intervals.
#' @param show_boundary Highlight the NMB = 0 decision boundary.
#' @param return_data Return prepared plotting data.
#'
#' @details
#' The heatmap representation uses categorical scenario axes
#' for three-level TWSA and numerical axes for denser grids.
#'
#' The contour representation always uses numerical parameter
#' values. Contour lines are interpolated from the evaluated
#' deterministic grid.
#'
#' Numerical cell boundaries are calculated from consecutive
#' parameter values without assuming equal spacing.
#'
#' Relative impacts are calculated against the corresponding
#' baseline-baseline combination within each analytical series.
#'
#' The NMB = 0 decision boundary is available only for
#' absolute NMB. It represents economic indifference between
#' the intervention and its comparator at the selected WTP.
#'
#' @return A ggplot object, a cea_multplots collection,
#'   or prepared plotting data.
#'
#' @export
#' @rawNamespace export(plot.twsa)
plot.twsa <- function(
    data,
    type = "heatmap",
    metric = "nmb",
    lambda = NULL,
    impact_mode = "absolute",
    mode = "Overall",
    facet_by = NULL,
    plot_by = NULL,
    filter_expr = NULL,
    facet_scales = "free",
    palette = c(
      lower = "#C0504D",
      upper = "#4472C4"
    ),
    midpoint = NULL,
    midpoint_color = "#FFFFFF",
    show_values = NULL,
    digits = 2,
    n_contours = 12L,
    show_boundary = TRUE,
    return_data = FALSE
) {

  `%||%` <- function(a, b) {
    if (!is.null(a)) a else b
  }

  # -----------------------------------------------------------------------
  # 1. Input validation
  # -----------------------------------------------------------------------

  if (!inherits(data, "twsa_result")) {
    stop("'data' must be a twsa_result object.")
  }

  type <- match.arg(
    type,
    c("heatmap", "contour")
  )

  metric <- match.arg(
    metric,
    c("nmb", "icer", "delta_cost", "delta_effect")
  )

  impact_mode <- match.arg(
    impact_mode,
    c("absolute", "relative")
  )

  mode <- match.arg(
    mode,
    c("Overall", "Subgroups")
  )

  allowed_facets <- c(
    "none",
    "dataset",
    "comparison",
    "pair",
    "subgroup",
    "subgroup_var",
    "subgroup_level"
  )

  allowed_plots <- c(
    "none",
    "dataset",
    "comparison",
    "pair",
    "subgroup_var",
    "subgroup_level"
  )

  validate_directive <- function(value, allowed, argument) {

    if (is.null(value)) {
      return(invisible(TRUE))
    }

    if (!is.character(value) ||
        length(value) != 1L ||
        is.na(value) ||
        !value %in% allowed) {

      stop(
        "'", argument, "' must be one of: ",
        paste(allowed, collapse = ", ")
      )
    }

    invisible(TRUE)
  }

  validate_directive(
    facet_by,
    allowed_facets,
    "facet_by"
  )

  validate_directive(
    plot_by,
    allowed_plots,
    "plot_by"
  )

  if (!is.character(facet_scales) ||
      length(facet_scales) != 1L ||
      is.na(facet_scales) ||
      !facet_scales %in% c(
        "fixed", "free", "free_x", "free_y"
      )) {

    stop("Invalid 'facet_scales'.")
  }

  validate_flag <- function(value, argument) {

    if (!is.logical(value) ||
        length(value) != 1L ||
        is.na(value)) {

      stop(
        "'", argument, "' must be TRUE or FALSE."
      )
    }

    invisible(TRUE)
  }

  validate_flag(show_boundary, "show_boundary")
  validate_flag(return_data, "return_data")

  if (!is.null(show_values)) {
    validate_flag(show_values, "show_values")
  }

  if (!is.numeric(digits) ||
      length(digits) != 1L ||
      is.na(digits) ||
      !is.finite(digits) ||
      digits < 0 ||
      digits != floor(digits)) {

    stop(
      "'digits' must be a non-negative integer."
    )
  }

  if (!is.numeric(n_contours) ||
      length(n_contours) != 1L ||
      is.na(n_contours) ||
      !is.finite(n_contours) ||
      n_contours < 2 ||
      n_contours != floor(n_contours)) {

    stop(
      "'n_contours' must be an integer >= 2."
    )
  }

  if (!is.character(palette) ||
      length(palette) != 2L ||
      anyNA(palette)) {

    stop(
      "'palette' must contain two colours."
    )
  }

  if (!is.character(midpoint_color) ||
      length(midpoint_color) != 1L ||
      is.na(midpoint_color)) {

    stop(
      "'midpoint_color' must be a single colour."
    )
  }

  if (!is.null(midpoint) &&
      (!is.numeric(midpoint) ||
       length(midpoint) != 1L ||
       !is.finite(midpoint))) {

    stop(
      "'midpoint' must be a finite numeric value."
    )
  }

  # Validate colour specifications.

  valid_colour <- function(x) {

    tryCatch(
      {
        grDevices::col2rgb(x)
        TRUE
      },
      error = function(e) FALSE
    )
  }

  if (!all(vapply(
    c(palette, midpoint_color),
    valid_colour,
    logical(1)
  ))) {

    stop("Invalid colour specification.")
  }

  # -----------------------------------------------------------------------
  # 2. Resolve graphical defaults
  # -----------------------------------------------------------------------

  resolved_plot <- plot_by %||% "pair"

  resolved_facet <- facet_by %||%
    if (mode == "Subgroups") {
      "subgroup"
    } else {
      "pair"
    }

  n_levels <- data$settings$n_levels %||% 3L

  if (!is.numeric(n_levels) ||
      length(n_levels) != 1L ||
      is.na(n_levels) ||
      !is.finite(n_levels) ||
      n_levels < 3L ||
      n_levels %% 2 != 1) {

    stop("Invalid TWSA grid resolution.")
  }

  dense_grid <- n_levels > 3L

  resolved_show_values <- show_values %||%
    (type == "heatmap" && !dense_grid)

  if (type == "contour" &&
      n_levels < 5L &&
      !return_data) {

    warning(
      "Contour plots based on fewer than five levels ",
      "may provide limited detail.",
      call. = FALSE
    )
  }

  # -----------------------------------------------------------------------
  # 3. Resolve economic metric
  # -----------------------------------------------------------------------

  selected_lambda <- NULL

  if (metric == "nmb") {

    available_lambda <- data$settings$lambda

    if (!is.numeric(available_lambda) ||
        length(available_lambda) == 0L ||
        any(!is.finite(available_lambda))) {

      stop(
        "No valid WTP thresholds available."
      )
    }

    if (is.null(lambda)) {

      if (length(available_lambda) != 1L) {

        stop(
          "Multiple WTP thresholds available. ",
          "Specify 'lambda'."
        )
      }

      selected_lambda <- available_lambda

    } else {

      if (!is.numeric(lambda) ||
          length(lambda) != 1L ||
          !is.finite(lambda) ||
          !lambda %in% available_lambda) {

        stop(
          "Selected lambda is not available."
        )
      }

      selected_lambda <- lambda
    }

    metric_column <- paste0(
      "NMB_",
      selected_lambda
    )

  } else {

    metric_column <- metric

    if (!is.null(lambda)) {

      warning(
        "'lambda' is ignored for metric = '",
        metric, "'.",
        call. = FALSE
      )
    }
  }

  # -----------------------------------------------------------------------
  # 4. Extract and validate results
  # -----------------------------------------------------------------------

  df <- data$sensitivity_results

  required <- c(
    "dataset",
    "subgroup_var",
    "subgroup_level",
    "comparison",
    "pair_uid",
    "parameter_1",
    "parameter_2",
    "scenario_1",
    "scenario_2",
    "value_1",
    "value_2",
    metric_column
  )

  missing_columns <- setdiff(
    required,
    names(df)
  )

  if (length(missing_columns) > 0L) {

    stop(
      "Missing TWSA columns: ",
      paste(
        missing_columns,
        collapse = ", "
      )
    )
  }

  if (!is.numeric(df$value_1) ||
      !is.numeric(df$value_2) ||
      any(!is.finite(df$value_1)) ||
      any(!is.finite(df$value_2))) {

    stop(
      "Invalid numerical parameter values."
    )
  }

  if (anyNA(df$scenario_1) ||
      anyNA(df$scenario_2)) {

    stop(
      "Invalid TWSA scenario identifiers."
    )
  }

  # -----------------------------------------------------------------------
  # 5. Select analytical mode
  # -----------------------------------------------------------------------

  if (mode == "Overall") {

    keep <- is.na(df$subgroup_var) |
      df$subgroup_var == "Overall"

  } else {

    keep <- !is.na(df$subgroup_var) &
      df$subgroup_var != "Overall"
  }

  df <- df[
    keep,
    ,
    drop = FALSE
  ]

  if (nrow(df) == 0L) {

    stop(
      "No results available for the selected mode."
    )
  }

  # -----------------------------------------------------------------------
  # 6. Prepare analytical identifiers
  # -----------------------------------------------------------------------

  df$pair <- paste(
    df$parameter_1,
    "vs",
    df$parameter_2
  )

  df$subgroup <- paste(
    df$subgroup_var,
    df$subgroup_level,
    sep = ": "
  )

  baseline_keys <- c(
    "dataset",
    "subgroup_var",
    "subgroup_level",
    "comparison",
    "pair_uid"
  )

  # Stable identifiers for analytical series and panels.

  make_key <- function(x, columns) {

    if (length(columns) == 0L) {

      return(
        rep("all", nrow(x))
      )
    }

    do.call(
      interaction,
      c(
        lapply(
          x[columns],
          function(z) {

            z <- as.character(z)
            z[is.na(z)] <- "<NA>"

            z
          }
        ),
        list(
          drop = TRUE,
          lex.order = TRUE
        )
      )
    )
  }

  # -----------------------------------------------------------------------
  # 7. Calculate analytical baselines
  # -----------------------------------------------------------------------

  df$original_value <- df[[metric_column]]

  baseline_rows <- df[
    df$scenario_1 == "baseline" &
      df$scenario_2 == "baseline",
    c(
      baseline_keys,
      "original_value"
    ),
    drop = FALSE
  ]

  if (nrow(baseline_rows) == 0L) {

    stop(
      "No baseline-baseline scenarios available."
    )
  }

  if (anyDuplicated(
    baseline_rows[baseline_keys]
  )) {

    stop(
      "Duplicated analytical baseline combinations."
    )
  }

  names(baseline_rows)[
    names(baseline_rows) == "original_value"
  ] <- "baseline_value"

  baseline_index <- match(
    as.character(
      make_key(df, baseline_keys)
    ),
    as.character(
      make_key(baseline_rows, baseline_keys)
    )
  )

  if (anyNA(baseline_index)) {

    stop(
      "Missing baseline for one or more ",
      "analytical combinations."
    )
  }

  df$baseline_value <-
    baseline_rows$baseline_value[baseline_index]

  if (impact_mode == "relative") {

    df$plot_value <-
      df$original_value - df$baseline_value

  } else {

    df$plot_value <- df$original_value
  }

  # -----------------------------------------------------------------------
  # 8. Apply optional filtering
  # -----------------------------------------------------------------------

  # Filtering occurs after baseline identification so that
  # relative impacts remain valid even when the filter excludes
  # the baseline-baseline scenario.

  if (!is.null(filter_expr)) {

    if (!is.character(filter_expr) ||
        length(filter_expr) != 1L ||
        is.na(filter_expr) ||
        !nzchar(filter_expr)) {

      stop(
        "'filter_expr' must be a non-empty string."
      )
    }

    df <- dplyr::filter(
      df,
      !!rlang::parse_expr(filter_expr)
    )
  }

  if (nrow(df) == 0L) {

    stop(
      "No results available after filtering."
    )
  }

  # -----------------------------------------------------------------------
  # 9. Validate analytical combinations
  # -----------------------------------------------------------------------

  scenario_keys <- c(
    baseline_keys,
    "scenario_1",
    "scenario_2"
  )

  if (anyDuplicated(
    df[scenario_keys]
  )) {

    stop(
      "Duplicated TWSA scenario combinations."
    )
  }

  # -----------------------------------------------------------------------
  # 10. Prepare categorical scenarios
  # -----------------------------------------------------------------------

  if (type == "heatmap" && !dense_grid) {

    scenario_levels <- c(
      "lower",
      "baseline",
      "upper"
    )

    if (!all(
      df$scenario_1 %in% scenario_levels
    ) ||
    !all(
      df$scenario_2 %in% scenario_levels
    )) {

      stop(
        "Invalid three-level TWSA scenarios."
      )
    }

    df$scenario_1 <- factor(
      df$scenario_1,
      levels = scenario_levels,
      labels = c(
        "Lower",
        "Baseline",
        "Upper"
      )
    )

    df$scenario_2 <- factor(
      df$scenario_2,
      levels = scenario_levels,
      labels = c(
        "Lower",
        "Baseline",
        "Upper"
      )
    )
  }

  # -----------------------------------------------------------------------
  # 11. Prepare numerical labels
  # -----------------------------------------------------------------------

  df$value_label <- ifelse(
    is.finite(df$plot_value),
    formatC(
      df$plot_value,
      format = "f",
      digits = digits,
      big.mark = ","
    ),
    "NA"
  )

  # -----------------------------------------------------------------------
  # 12. Calculate numerical cell boundaries
  # -----------------------------------------------------------------------

  compute_boundaries <- function(values) {

    values <- sort(
      unique(values)
    )

    if (length(values) < 2L) {

      stop(
        "At least two distinct parameter values ",
        "are required."
      )
    }

    if (any(diff(values) <= 0)) {

      stop(
        "Parameter values must be strictly increasing."
      )
    }

    midpoints <- (
      values[-1L] +
        values[-length(values)]
    ) / 2

    data.frame(
      value = values,
      lower = c(
        values[1L],
        midpoints
      ),
      upper = c(
        midpoints,
        values[length(values)]
      )
    )
  }

  prepare_surface <- function(plot_df) {

    grid_groups <- split(
      plot_df,
      make_key(
        plot_df,
        baseline_keys
      ),
      drop = TRUE
    )

    surface_parts <- lapply(
      grid_groups,
      function(g) {

        if (anyDuplicated(
          g[c("value_1", "value_2")]
        )) {

          stop(
            "Duplicated numerical grid coordinates."
          )
        }

        nx <- length(
          unique(g$value_1)
        )

        ny <- length(
          unique(g$value_2)
        )

        if (nx < 2L || ny < 2L) {

          stop(
            "Insufficient numerical grid resolution."
          )
        }

        if (nrow(g) != nx * ny) {

          stop(
            "Incomplete numerical grid. ",
            "Contour and surface representations ",
            "require all parameter combinations."
          )
        }

        x_bounds <- compute_boundaries(
          g$value_1
        )

        y_bounds <- compute_boundaries(
          g$value_2
        )

        x_index <- match(
          g$value_1,
          x_bounds$value
        )

        y_index <- match(
          g$value_2,
          y_bounds$value
        )

        g$xmin <- x_bounds$lower[x_index]
        g$xmax <- x_bounds$upper[x_index]

        g$ymin <- y_bounds$lower[y_index]
        g$ymax <- y_bounds$upper[y_index]

        g
      }
    )

    dplyr::bind_rows(
      surface_parts
    )
  }

  # -----------------------------------------------------------------------
  # 13. Validate plotting panels
  # -----------------------------------------------------------------------

  validate_panels <- function(plot_df) {

    panel_keys <- switch(
      resolved_facet,
      none = character(0),
      subgroup = c(
        "subgroup_var",
        "subgroup_level"
      ),
      resolved_facet
    )

    panels <- if (
      length(panel_keys) == 0L
    ) {

      list(plot_df)

    } else {

      split(
        plot_df,
        make_key(
          plot_df,
          panel_keys
        ),
        drop = TRUE
      )
    }

    for (panel in panels) {

      axis_pairs <- unique(
        panel[c(
          "parameter_1",
          "parameter_2"
        )]
      )

      if (nrow(axis_pairs) > 1L) {

        stop(
          "Incompatible parameter axes within a panel. ",
          "Use plot_by = 'pair' or facet_by = 'pair' ",
          "to separate parameter pairs.",
          call. = FALSE
        )
      }

      analytical_series <- unique(
        panel[baseline_keys]
      )

      if (nrow(analytical_series) > 1L) {

        stop(
          "Multiple analytical surfaces overlap ",
          "within a plotting panel. ",
          "Separate datasets, comparisons or subgroups ",
          "using plot_by, facet_by or filter_expr.",
          call. = FALSE
        )
      }
    }

    invisible(TRUE)
  }

  # -----------------------------------------------------------------------
  # 14. Resolve graphical labels
  # -----------------------------------------------------------------------

  metric_title <- switch(
    metric,
    nmb = "Net Monetary Benefit",
    icer = "Incremental Cost-Effectiveness Ratio",
    delta_cost = "Incremental Cost",
    delta_effect = "Incremental Effectiveness"
  )

  legend_label <- switch(
    metric,
    nmb = "NMB",
    icer = "ICER",
    delta_cost = "\u0394 Cost",
    delta_effect = "\u0394 Effect"
  )

  resolved_midpoint <- midpoint %||%
    if (
      metric == "nmb" ||
      impact_mode == "relative"
    ) {

      0

    } else {

      NULL
    }

  # -----------------------------------------------------------------------
  # 15. Build graphical representation
  # -----------------------------------------------------------------------

  build_plot <- function(plot_df, plot_label = NULL) {

    validate_panels(plot_df)

    categorical_heatmap <- (
      type == "heatmap" &&
        !dense_grid
    )

    if (!categorical_heatmap) {

      plot_df <- prepare_surface(
        plot_df
      )
    }

    if (!any(
      is.finite(plot_df$plot_value)
    )) {

      stop(
        "No finite economic values available."
      )
    }

    plot_df$contour_group <- as.integer(
      make_key(
        plot_df,
        baseline_keys
      )
    )

    unique_pairs <- unique(
      plot_df$pair_uid
    )

    if (length(unique_pairs) == 1L) {

      x_label <- unique(
        plot_df$parameter_1
      )[1]

      y_label <- unique(
        plot_df$parameter_2
      )[1]

    } else {

      x_label <- "Parameter 1"
      y_label <- "Parameter 2"
    }

    # ---------------------------------------------------------------------
    # 15.1. Surface geometry
    # ---------------------------------------------------------------------

    if (categorical_heatmap) {

      p <- ggplot2::ggplot(
        plot_df,
        ggplot2::aes(
          x = scenario_1,
          y = scenario_2,
          fill = plot_value
        )
      ) +
        ggplot2::geom_tile(
          colour = "white",
          linewidth = 0.7
        )

    } else {

      cell_colour <- if (
        type == "contour"
      ) {

        NA_character_

      } else {

        "white"
      }

      cell_width <- if (
        type == "contour"
      ) {

        0.12

      } else {

        0.15
      }

      p <- ggplot2::ggplot(
        plot_df,
        ggplot2::aes(
          x = value_1,
          y = value_2
        )
      ) +
        ggplot2::geom_rect(
          ggplot2::aes(
            xmin = xmin,
            xmax = xmax,
            ymin = ymin,
            ymax = ymax,
            fill = plot_value
          ),
          colour = cell_colour,
          linewidth = cell_width
        ) +
        ggplot2::scale_x_continuous(
          expand = ggplot2::expansion(
            mult = 0
          )
        ) +
        ggplot2::scale_y_continuous(
          expand = ggplot2::expansion(
            mult = 0
          )
        ) +
        ggplot2::coord_cartesian(
          expand = FALSE
        )
    }

    # ---------------------------------------------------------------------
    # 15.2. Shared colour scale
    # ---------------------------------------------------------------------

    colour_guide <- ggplot2::guide_colorbar(
      barheight = grid::unit(
        65, "mm"
      ),
      barwidth = grid::unit(
        5, "mm"
      )
    )

    if (is.null(resolved_midpoint)) {

      p <- p +
        ggplot2::scale_fill_gradient(
          low = unname(
            palette[1]
          ),
          high = unname(
            palette[2]
          ),
          name = legend_label,
          na.value = "grey85",
          guide = colour_guide
        )

    } else {

      p <- p +
        ggplot2::scale_fill_gradient2(
          low = unname(
            palette[1]
          ),
          mid = midpoint_color,
          high = unname(
            palette[2]
          ),
          midpoint = resolved_midpoint,
          name = legend_label,
          na.value = "grey85",
          guide = colour_guide
        )
    }

    # ---------------------------------------------------------------------
    # 15.3. Numerical labels
    # ---------------------------------------------------------------------

    if (resolved_show_values &&
        type == "heatmap") {

      if (categorical_heatmap) {

        p <- p +
          ggplot2::geom_text(
            ggplot2::aes(
              label = value_label
            ),
            size = 3.4
          )

      } else {

        p <- p +
          ggplot2::geom_text(
            ggplot2::aes(
              x = value_1,
              y = value_2,
              label = value_label
            ),
            inherit.aes = FALSE,
            size = 2.5
          )
      }
    }

    # ---------------------------------------------------------------------
    # 15.4. Contour lines
    # ---------------------------------------------------------------------

    if (type == "contour") {

      contour_data <- plot_df[
        is.finite(
          plot_df$plot_value
        ),
        ,
        drop = FALSE
      ]

      p <- p +
        ggplot2::geom_contour(
          data = contour_data,
          mapping = ggplot2::aes(
            x = value_1,
            y = value_2,
            z = plot_value,
            group = contour_group
          ),
          inherit.aes = FALSE,
          bins = n_contours,
          colour = "#808080",
          linewidth = 0.20,
          na.rm = TRUE
        )
    }

    # ---------------------------------------------------------------------
    # 15.5. Economic decision boundary
    # ---------------------------------------------------------------------

    eligible_boundary <- (
      show_boundary &&
        metric == "nmb" &&
        impact_mode == "absolute"
    )

    if (eligible_boundary) {

      boundary_data <- plot_df

      # Categorical heatmaps use numerical coordinates for
      # the decision boundary while preserving categorical axes.
      #
      # Numerical contour geometry is therefore available
      # directly for contour and dense heatmap representations.

      if (!categorical_heatmap) {

        grid_groups <- split(
          boundary_data,
          make_key(
            boundary_data,
            baseline_keys
          ),
          drop = TRUE
        )

        # Keep only analytical surfaces where NMB crosses zero.

        crossing_groups <- lapply(
          grid_groups,
          function(g) {

            z <- g$plot_value
            z <- z[is.finite(z)]

            if (
              length(z) > 0L &&
              min(z) < 0 &&
              max(z) > 0
            ) {

              return(g)
            }

            NULL
          }
        )

        crossing_groups <- Filter(
          Negate(is.null),
          crossing_groups
        )

        # Add the decision boundary only to eligible surfaces.

        if (length(crossing_groups) > 0L) {

          boundary_data <- dplyr::bind_rows(
            crossing_groups
          )

          p <- p +
            ggplot2::geom_contour(
              data = boundary_data,
              mapping = ggplot2::aes(
                x = value_1,
                y = value_2,
                z = plot_value,
                group = contour_group
              ),
              inherit.aes = FALSE,
              breaks = 0,
              colour = "#454545",
              linewidth = 0.80,
              na.rm = TRUE
            )
        }
      }
    }

    # ---------------------------------------------------------------------
    # 15.6. Faceting
    # ---------------------------------------------------------------------

    if (
      resolved_facet == "subgroup"
    ) {

      p <- p +
        ggplot2::facet_grid(
          rows = ggplot2::vars(
            subgroup_level
          ),
          cols = ggplot2::vars(
            subgroup_var
          ),
          scales = facet_scales
        )

    } else if (
      resolved_facet != "none" &&
      !(
        resolved_facet == "pair" &&
        length(unique_pairs) == 1L
      )
    ) {

      p <- p +
        ggplot2::facet_wrap(
          ggplot2::vars(
            !!rlang::sym(
              resolved_facet
            )
          ),
          scales = if (
            type == "heatmap" && !dense_grid
          ) {
            "fixed"
          } else {
            facet_scales
          },
          axes = "margins",
          axis.labels = "margins"
        )
    }

    # ---------------------------------------------------------------------
    # 15.7. Titles and labels
    # ---------------------------------------------------------------------

    subtitle <- paste0(
      metric_title,
      if (
        impact_mode == "relative"
      ) {

        " - Change from baseline"

      } else {

        " - Absolute values"
      }
    )

    if (metric == "nmb") {

      subtitle <- paste0(
        subtitle,
        " | WTP = ",
        format(
          selected_lambda,
          big.mark = ",",
          scientific = FALSE,
          trim = TRUE
        ),
        "/QALY"
      )
    }

    if (!is.null(plot_label)) {

      subtitle <- paste0(
        subtitle,
        "\n",
        plot_label
      )
    }

    # ---------------------------------------------------------------------
    # 15.8. Final presentation
    # ---------------------------------------------------------------------

    p <- p +
      ggplot2::labs(
        title = "Two-Way Sensitivity Analysis",
        subtitle = subtitle,
        x = x_label,
        y = y_label
      ) +
      ggplot2::theme_bw() +
      ggplot2::theme(
        panel.grid.major =
          ggplot2::element_blank(),
        panel.grid.minor =
          ggplot2::element_blank(),
        strip.background =
          ggplot2::element_rect(
            fill = "grey92",
            colour = NA
          ),
        strip.text =
          ggplot2::element_text(
            face = "bold"
          ),
        plot.title =
          ggplot2::element_text(
            face = "bold",
            size = 13
          ),
        plot.subtitle =
          ggplot2::element_text(
            size = 10,
            lineheight = 1.2
          ),
        legend.title =
          ggplot2::element_text(
            face = "bold"
          )
      )

    return(p)
  }

  # -----------------------------------------------------------------------
  # 16. Return prepared data
  # -----------------------------------------------------------------------

  if (
    return_data &&
    resolved_plot == "none"
  ) {

    return(df)
  }

  # -----------------------------------------------------------------------
  # 17. Single plot
  # -----------------------------------------------------------------------

  if (
    resolved_plot == "none"
  ) {

    return(
      build_plot(df)
    )
  }

  # -----------------------------------------------------------------------
  # 18. Independent plots
  # -----------------------------------------------------------------------

  plot_levels <- sort(
    unique(
      as.character(
        df[[resolved_plot]]
      )
    )
  )

  output <- vector(
    "list",
    length(plot_levels)
  )

  names(output) <- plot_levels

  for (level in plot_levels) {

    plot_df <- df[
      as.character(
        df[[resolved_plot]]
      ) == level,
      ,
      drop = FALSE
    ]

    output[[level]] <- if (
      return_data
    ) {

      plot_df

    } else {

      build_plot(
        plot_df,
        plot_label = level
      )
    }
  }

  # -----------------------------------------------------------------------
  # 19. Shared multiple-plots handler
  # -----------------------------------------------------------------------

  if (!return_data) {

    output <- cea_multplots_handler(
      output,
      plot_type = paste0(
        "TWSA ",
        type
      )
    )
  }

  return(output)
}
